"""Self-contained, offline presentation of computed RegionResultV1 JSON."""
from __future__ import annotations

import json


def render_html(results: list[dict]) -> str:
    payload = json.dumps(results, ensure_ascii=False, allow_nan=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'">
<title>SCI-REGIONS v1 — offline research comparison</title>
<style>
:root{font:15px/1.45 system-ui,sans-serif;color:#182330;background:#f5f7f8}body{max-width:1180px;margin:auto;padding:20px}h1{margin-bottom:4px}h2{font-size:1.25rem}header p{max-width:85ch}button,select{font:inherit;padding:.45rem .65rem;cursor:pointer}button[aria-pressed=true]{background:#15355b;color:white}nav,.controls{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.panel{background:white;border:1px solid #cbd5dc;border-radius:10px;padding:16px;margin:12px 0}#map{width:min(100%,740px);height:auto;border:1px solid #ccd}#map rect.cell{cursor:pointer;stroke:#fff;stroke-width:.4}#map rect.cell:hover{stroke:#111;stroke-width:2}.muted{color:#4e626e}.warning{background:#fff3d7;border-left:4px solid #a97700;padding:10px}.legend{display:flex;gap:15px;flex-wrap:wrap}.key{display:inline-flex;align-items:center;gap:5px}.swatch{display:inline-block;width:16px;height:16px;border:1px solid #555}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #d8e0e5;text-align:left;padding:5px;vertical-align:top}th{position:sticky;top:0;background:#fff}.scroll{max-height:360px;overflow:auto}svg text{font:11px system-ui,sans-serif}#detail{white-space:pre-wrap}code{font-size:.9em}a{color:#155488}
</style></head><body>
<header><h1>Where could the pricing comparison change?</h1><p class="muted">SCI-REGIONS v1 · exploratory R3-B tier X · pinned local model. Checked coordinates and conditional assumptions only. Area and colour do not express probability. Revenue preferences use float point estimates with a heuristic roundoff screen, not certified numerical or statistical intervals. This study does not compare with a current deployed result.</p></header>
<div class="panel"><label for="model">Frozen model reading:</label> <select id="model"><option value="0">Net additions</option><option value="1">Gross additions</option></select><p id="assumptions" class="muted"></p><p class="warning">Some declared options have missing intervention values. Named preferences apply only to the listed comparison set; whole-decision comparison can remain incomplete.</p></div>
<nav aria-label="Presentation"><button data-view="point" aria-pressed="true">Matched point</button><button data-view="threshold" aria-pressed="false">Threshold plus question</button><button data-view="map" aria-pressed="false">Two-dimensional region</button></nav>
<section id="point" class="panel"><h2>Matched point: direct churn 0.5 pp per £10, competitive response £0/month</h2><div id="point-body"></div></section>
<section id="threshold" class="panel" hidden><h2>One-axis checks at competitive response £0/month</h2><p>Each row is an evaluated coordinate. Changes between rows are brackets, not exact thresholds.</p><div id="threshold-body"></div></section>
<section id="map-panel" class="panel" hidden><h2>Two-dimensional evaluated points</h2><div class="controls"><button data-layer="preference" aria-pressed="true">Preference</button><button data-layer="feasibility" aria-pressed="false">Feasibility</button></div><div class="legend"><span class="key"><span class="swatch" style="background:#2c775e"></span>Keep current pricing</span><span class="key"><span class="swatch" style="background:repeating-linear-gradient(45deg,#4d7cb4 0 4px,#edf4fa 4px 5px)"></span>£49 with feature</span><span class="key"><span class="swatch" style="background:radial-gradient(#f5eafb 25%,transparent 27%) 0 0/6px 6px,#8660a5"></span>£59 with feature</span><span class="key"><span class="swatch" style="background:#cb735e"></span>No feasible option</span><span class="key"><span class="swatch" style="background:#e9b65d"></span>Tie or unresolved</span><span class="key"><span class="swatch" style="background:#9baab4"></span>Missing or unsupported</span></div><p class="muted">Option patterns show point-estimate preference only among the three computable options. The six-option comparison remains incomplete.</p><svg id="map" viewBox="0 0 710 590" role="img" aria-label="Checked scenario coordinates"></svg><div class="controls"><label for="map-x">Inspect grid churn response (pp per £10)</label><select id="map-x"></select><label for="map-y">Competitive response (GBP/month)</label><select id="map-y"></select><button id="inspect-grid">Inspect evaluated point</button></div><p class="muted">The rectangles and selectors locate sampled grid coordinates. Their interiors have no certification. The marked (0.5, 0) research reference point was evaluated separately from the grid.</p><details><summary>Table alternative: all evaluated coordinates</summary><div id="map-table" class="scroll"></div></details></section>
<section class="panel"><h2>Selected coordinate and evidence</h2><div id="detail" aria-live="polite"></div></section>
<script id="data" type="application/json">__DATA__</script>
<script>
const all=JSON.parse(document.getElementById('data').textContent);const requestedView=new URLSearchParams(location.search).get('arm'),lockedView=['point','threshold','map'].includes(requestedView)?requestedView:null;let selected=0,view=lockedView||'point',layer='preference',selectedPoint={x:.5,y:0};const $=id=>document.getElementById(id);if(lockedView){document.querySelector('nav[aria-label="Presentation"]').hidden=true;$('model').disabled=true}const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const number=x=>x===null?'unknown':Number(x).toLocaleString('en-GB',{maximumFractionDigits:5});
function active(){return all[selected]}function locate(r,x,y){return r.points.find(p=>p.x===x&&p.y===y)}
function rowClass(p){if(p.state!=='EVALUATED')return 'missing';if(layer==='feasibility'){const states=Object.values(p.options).map(o=>o.feasibility);if(states.every(s=>s==='INFEASIBLE'))return 'none';if(states.some(s=>s==='FEASIBLE'))return 'feasible';return 'missing'}const prefix=['POINT_ESTIMATE_PREFERRED:','PREFERRED:'].find(s=>p.named_preference.startsWith(s));if(prefix){const id=p.named_preference.slice(prefix.length);return ({keep_current_pricing:'pref_keep','49_with_feature_release':'pref_49','59_with_feature_release':'pref_59'})[id]||'preferred_other'}if(p.named_preference==='NO_FEASIBLE_OPTION')return 'none';if(['EXACT_TIE','PRACTICALLY_EQUIVALENT','NUMERICALLY_UNRESOLVED'].includes(p.named_preference))return 'tie';return 'missing'}
const colours={pref_keep:'#2c775e',pref_49:'url(#p49)',pref_59:'url(#p59)',preferred_other:'#327f73',feasible:'#2c775e',none:'url(#pnone)',tie:'url(#ptie)',missing:'url(#pmissing)'};
function detail(p){if(!p){$('detail').textContent='No point selected';return}selectedPoint={x:p.x,y:p.y};const r=active(),q=r.request;let s='<p><strong>'+esc(q.axes[0].label)+'</strong>: '+number(p.x)+' '+esc(q.axes[0].unit)+'; <strong>'+esc(q.axes[1].label)+'</strong>: '+number(p.y)+' '+esc(q.axes[1].unit)+'</p><p>State: '+esc(p.state)+' · named comparison: '+esc(p.named_preference)+' · whole comparison: '+esc(p.overall_preference)+'</p>';if(p.state==='EVALUATED'){s+='<table><thead><tr><th>Option</th><th>Goal</th><th>Churn limit</th><th>Feasibility</th><th>Month-12 MRR</th><th>Reason</th></tr></thead><tbody>';for(const id of q.option_ids){const o=p.options[id],c=o.constraints[0];s+='<tr><td>'+esc(q.option_labels[id])+' <code>'+esc(id)+'</code></td><td>'+esc(o.goal)+' ('+number(o.goal_value)+')</td><td>'+esc(c?.state??'none')+' ('+number(c?.value??null)+')</td><td>'+esc(o.feasibility)+'</td><td>£'+number(o.objective_value)+'</td><td>'+esc(o.reason??'—')+'</td></tr>'}s+='</tbody></table><p>Evidence tier: '+esc(q.source.tier)+' · comparison set: '+q.comparison_set.map(id=>esc(q.option_labels[id])).join(', ')+'</p><p>Next question candidate: '+esc(p.question?.text??'none')+' ('+esc(p.question?.evidence_id??'')+')</p>'} $('detail').innerHTML=s}
function pointView(){const r=active(),p=locate(r,.5,0);$('point-body').innerHTML='<p>Goal attainment, churn feasibility and terminal-revenue preference are separate. Baseline status: '+esc(r.reference.status)+'.</p><p>Named comparison: <strong>'+esc(p?.named_preference??'not evaluated')+'</strong>; whole comparison: <strong>'+esc(p?.overall_preference??'not evaluated')+'</strong>.</p>';detail(p)}
function thresholdView(){const r=active(),xs=r.request.axes[0].grid_values,rows=xs.map(x=>locate(r,x,0)).filter(Boolean);let h='<table><thead><tr><th>Churn response (pp/£10)</th><th>Named preference</th><th>£59 goal</th><th>£59 churn limit</th><th>Next question</th></tr></thead><tbody>';for(const p of rows){const o=p.options['59_with_feature_release'];h+='<tr><td>'+number(p.x)+'</td><td>'+esc(p.named_preference)+'</td><td>'+esc(o?.goal??'unknown')+'</td><td>'+esc(o?.constraints?.[0]?.state??'unknown')+'</td><td>'+esc(p.question?.text??'none')+'</td></tr>'}h+='</tbody></table>';const brackets=r.transition_brackets.filter(b=>b.axis_id==='churn_response'&&b.fixed_axis_value===0);h+='<p>Observed transition brackets: '+(brackets.length?brackets.map(b=>'['+number(b.low)+', '+number(b.high)+'] '+b.kinds.join('/')).join('; '):'none on this grid')+'.</p>';$('threshold-body').innerHTML=h}
function mapView(){const r=active(),q=r.request,xs=q.axes[0].grid_values,ys=q.axes[1].grid_values,svg=$('map'),ns='http://www.w3.org/2000/svg';while(svg.firstChild)svg.removeChild(svg.firstChild);svg.innerHTML='<defs><pattern id="p49" width="6" height="6" patternUnits="userSpaceOnUse"><rect width="6" height="6" fill="#4d7cb4"/><path d="M-1 1L5 7M1 -1L7 5" stroke="#edf4fa" stroke-width="1.2"/></pattern><pattern id="p59" width="6" height="6" patternUnits="userSpaceOnUse"><rect width="6" height="6" fill="#8660a5"/><circle cx="3" cy="3" r="1.5" fill="#f5eafb"/></pattern><pattern id="pnone" width="6" height="6" patternUnits="userSpaceOnUse"><rect width="6" height="6" fill="#cb735e"/><path d="M0 0L6 6M6 0L0 6" stroke="#fff" stroke-width=".8"/></pattern><pattern id="ptie" width="6" height="6" patternUnits="userSpaceOnUse"><rect width="6" height="6" fill="#e9b65d"/><path d="M0 3H6" stroke="#543e14" stroke-width=".8"/></pattern><pattern id="pmissing" width="6" height="6" patternUnits="userSpaceOnUse"><rect width="6" height="6" fill="#9baab4"/><path d="M0 0L6 6" stroke="#fff" stroke-width=".8"/></pattern></defs>';const add=(tag,attrs,text)=>{const n=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;svg.appendChild(n);return n};const x0=65,y0=30,w=580,h=480,dx=w/xs.length,dy=h/ys.length;add('rect',{x:x0,y:y0,width:w,height:h,fill:'#eee'});for(let j=0;j<ys.length;j++)for(let i=0;i<xs.length;i++){const p=locate(r,xs[i],ys[j]);if(!p)continue;const rect=add('rect',{class:'cell',x:x0+i*dx,y:y0+(ys.length-1-j)*dy,width:dx,height:dy,fill:colours[rowClass(p)]});rect.addEventListener('click',()=>detail(p));const title=document.createElementNS(ns,'title');title.textContent=xs[i]+', '+ys[j]+': '+p.named_preference;rect.appendChild(title)}add('circle',{cx:x0+(.5-xs[0])/(xs.at(-1)-xs[0])*w,cy:y0+h,r:6,fill:'#132b3b',stroke:'#fff','stroke-width':2});add('text',{x:65,y:535},'Churn response (percentage points per +£10)');add('text',{x:65,y:553},number(xs[0])+' to '+number(xs.at(-1)));add('text',{x:65,y:572},'Competitive response: '+number(ys[0])+' to '+number(ys.at(-1))+' GBP/month');let table='<table><thead><tr><th>x</th><th>y</th><th>State</th><th>Named preference</th><th>Whole comparison</th></tr></thead><tbody>';for(const p of r.points){table+='<tr><td>'+number(p.x)+'</td><td>'+number(p.y)+'</td><td>'+esc(p.state)+'</td><td>'+esc(p.named_preference)+'</td><td>'+esc(p.overall_preference)+'</td></tr>'}table+='</tbody></table>';$('map-table').innerHTML=table}
function mapCoordinateControls(){const r=active(),xs=r.request.axes[0].grid_values,ys=r.request.axes[1].grid_values,x=$('map-x'),y=$('map-y');x.innerHTML=xs.map(v=>'<option value="'+v+'">'+number(v)+'</option>').join('');y.innerHTML=ys.map(v=>'<option value="'+v+'">'+number(v)+'</option>').join('');x.value=String(xs.includes(selectedPoint.x)?selectedPoint.x:xs.reduce((best,v)=>Math.abs(v-selectedPoint.x)<Math.abs(best-selectedPoint.x)?v:best));y.value=String(ys.includes(selectedPoint.y)?selectedPoint.y:ys[0]);$('inspect-grid').onclick=()=>detail(locate(r,Number(x.value),Number(y.value)))}
function render(){const r=active();$('assumptions').textContent='Fixed assumptions: '+r.request.fixed_assumptions.map(a=>a.id+'='+a.value).join('; ')+'. Goal: first passage by month 12. Preference: month-12 MRR, delta=0. Source: '+r.request.source.commit+'.';$('point').hidden=view!=='point';$('threshold').hidden=view!=='threshold';$('map-panel').hidden=view!=='map';document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===view));document.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.layer===layer));if(view==='point')pointView();if(view==='threshold')thresholdView();if(view==='map'){mapView();mapCoordinateControls()}detail(locate(r,selectedPoint.x,selectedPoint.y)||locate(r,.5,0))}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(lockedView)return;view=b.dataset.view;render()});document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{layer=b.dataset.layer;render()});$('model').onchange=e=>{if(lockedView)return;selected=Number(e.target.value);render()};render();
</script></body></html>""".replace("__DATA__", payload)
